python3 -c "
import json
with open('/app/resources/treasury_bulletin_1980_11.json', 'r') as f:
    data = json.load(f)
doc = data.get('document', {})
elements = doc.get('elements', [])
# Look for text elements with savings notes data
for i, el in enumerate(elements):
    if el.get('type') == 'text':
        content = el.get('content', [])
        if content and len(content) > 0:
            # Check first cell content
            for row in content:
                if isinstance(row, list) and len(row) > 0:
                    first_cell = str(row[0])
                    if '1980' in first_cell and 'notes' in first_cell.lower():
                        print(f'Element {i}: {row}')
"
